using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using CityForge.Environment;
namespace CityForge.Editor {
[InitializeOnLoad] public static class RowlanPondStudy {
const string Root="Assets/CityForge/Art/Environment/RowlanPondStudy/";
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/work/";
static double captureAt;static RowlanPondStudy(){EditorApplication.update+=Tick;}
static Texture2D Tex(string name)=>AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/MicroVerse-Extras/Terrain Textures/Textures/"+name+"/"+name+"_BaseColor.png");
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isPlaying)return;if(File.Exists(Work+"rowlan-pond")){File.Delete(Work+"rowlan-pond");Run();}if(captureAt>0&&EditorApplication.timeSinceStartup>captureAt){captureAt=0;Capture();}}
[MenuItem("CityForge/Ground Study/Rowlan Pond Textures")]
static void Run(){var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/RollingPondStudy/RollingPondZoom1.unity");foreach(var go in scene.GetRootGameObjects()){if(!go.name.StartsWith("Ground with meadow")&&!go.name.StartsWith("Short meadow grass"))continue;var renderer=go.GetComponent<Renderer>();var mat=new Material(renderer.sharedMaterial);mat.shader=Shader.Find("CityForge/Rowlan Pond Ground");mat.SetTexture("_Grass",Tex("Grass 04"));mat.SetTexture("_DryGrass",Tex("Grass 06"));mat.SetTexture("_Forest",Tex("Leaves 02"));mat.SetTexture("_Dirt",Tex("Soil 01"));mat.SetTexture("_Stone",Tex("Gravel 01"));string path=Root+(go.name.StartsWith("Ground")?"Ground":"Grass")+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(mat,old);Object.DestroyImmediate(mat);mat=old;}else AssetDatabase.CreateAsset(mat,path);renderer.sharedMaterial=mat;}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"RowlanPondZoom1.unity");captureAt=EditorApplication.timeSinceStartup+3;}
static void Capture(){var reflection=Object.FindFirstObjectByType<PondPlanarReflection>();reflection.RenderNow();var camera=reflection.sourceCamera;var rt=new RenderTexture(3840,2160,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(3840,2160,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,3840,2160),0,0);t.Apply();File.WriteAllBytes("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/RowlanPond_Zoom1.png",t.EncodeToPNG());Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();Object.DestroyImmediate(rt);}Debug.Log("ROWLAN POND CAPTURE COMPLETE");}
}}
